import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { readQuotaSnapshot } from "@/lib/quota-usage";

describe.runIf(databaseTestsEnabled)(
  "gated quota rollout and plan transitions",
  () => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    beforeAll(async () => {
      fixture = await usageFixture();
      await setGating(boundary.db, true);
    });
    afterAll(async () => {
      if (fixture) await fixture.close();
    });
    it("counts sent and reserved Premium emails toward the 20-per-day allowance", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const first = await createCampaign(f.user.id, await f.input());
      const send = await boundary.db.send.findFirstOrThrow({
        where: { campaignId: first.id, campaign: { userId: f.user.id } },
      });
      expect(await deliverOne(f.user.id, send.id)).toMatchObject({
        outcome: "done",
      });
      await createCampaign(f.user.id, await f.input(10));
      await createCampaign(f.user.id, await f.input(8));
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        daily: { sent: 1, reserved: 18, used: 19, limit: 20, remaining: 1 },
        monthly: {
          sent: 1,
          reserved: 18,
          used: 19,
          limit: 300,
          remaining: 281,
        },
      });
      await createCampaign(f.user.id, await f.input());
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        daily: { sent: 1, reserved: 19, used: 20, limit: 20, remaining: 0 },
        monthly: {
          sent: 1,
          reserved: 19,
          used: 20,
          limit: 300,
          remaining: 280,
        },
      });
      await expect(
        createCampaign(f.user.id, await f.input()),
      ).rejects.toMatchObject({ allowance: "DAILY" });
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        daily: { sent: 1, reserved: 19, used: 20, limit: 20, remaining: 0 },
        monthly: { used: 20, limit: 300, remaining: 280 },
      });
    });
    it("uses paid billing periods and includes paid consumption when downgraded to the free calendar month", async () => {
      const f = await usageOwner(boundary.db, { paid: true });
      const campaign = await createCampaign(f.user.id, await f.input());
      const send = await boundary.db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      await deliverOne(f.user.id, send.id);
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        daily: { limit: 20 },
        monthly: { limit: 300, sent: 1 },
      });
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { plan: "FREE", subscriptionStatus: "EXPIRED" },
      });
      const downgraded = await readQuotaSnapshot(f.user.id);
      expect(downgraded).toMatchObject({
        plan: "FREE",
        daily: { sent: 1, limit: 3 },
        monthly: { sent: 1, limit: 15, remaining: 14 },
      });
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { plan: "PAID", subscriptionStatus: "ACTIVE" },
      });
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        monthly: { sent: 1, limit: 300, remaining: 299 },
      });
    });
    it("shares complimentary calendar consumption and pauses unresolved provider renewal without free credit", async () => {
      const f = await usageOwner(boundary.db);
      await createCampaign(f.user.id, await f.input());
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          planOverride: "PAID",
          planOverrideStartsAt: new Date(Date.now() - 1000),
          planOverrideReason: "Fixture grant",
        },
      });
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        plan: "PAID",
        monthly: { reserved: 1, limit: 300 },
      });
      const paid = await usageOwner(boundary.db, { paid: true });
      await boundary.db.user.update({
        where: { id: paid.user.id },
        data: {
          currentPeriodStart: new Date(Date.now() - 86400000 * 30),
          currentPeriodEnd: new Date(Date.now() - 1000),
        },
      });
      expect(await readQuotaSnapshot(paid.user.id)).toMatchObject({
        mode: "gated",
        sendingAllowed: false,
        monthly: { limit: 300 },
      });
      await expect(
        createCampaign(paid.user.id, await paid.input()),
      ).rejects.toMatchObject({ code: "BILLING_PERIOD_UNRESOLVED" });
    });
    it("does not invent a monthly period when a paid account has no verified provider dates", async () => {
      await setGating(boundary.db, true);
      const f = await usageOwner(boundary.db);
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { plan: "PAID", subscriptionStatus: "NONE" },
      });
      const snapshot = await readQuotaSnapshot(f.user.id);
      expect(snapshot).toMatchObject({
        mode: "gated",
        plan: "PAID",
        sendingAllowed: false,
        monthly: { remaining: 0, startsAt: null, endsAt: null },
      });
      expect(
        await boundary.db.usagePeriod.count({ where: { userId: f.user.id } }),
      ).toBe(0);
      await expect(
        createCampaign(f.user.id, await f.input()),
      ).rejects.toMatchObject({ code: "BILLING_PERIOD_UNRESOLVED" });
    });
    it("blocks incomplete accounting on activation and preserves rolling-200 behavior after rollback", async () => {
      const f = await usageOwner(boundary.db);
      await setGating(boundary.db, false);
      await createCampaign(f.user.id, await f.input(4));
      await setGating(boundary.db, true);
      await expect(
        createCampaign(f.user.id, await f.input()),
      ).rejects.toMatchObject({ allowance: "DAILY" });
      await setGating(boundary.db, false);
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        mode: "legacy",
        used: 4,
        limit: 200,
      });
      await createCampaign(f.user.id, await f.input());
      expect((await readQuotaSnapshot(f.user.id)).used).toBe(5);
    });
  },
);
